INSERT IGNORE INTO VIDEOS (CANAL_ID, YT_VIDEO_ID, TITULO, DURACAO_SEG, TIPO, THUMB, STATUS, ORDEM, DESCOBERTA, CRIADO_EM, ATUALIZADO_EM) SELECT {{canalId}}, YT, TITULO, DUR, TIPO, THUMB, 'FILA', POS, '{{descoberta}}', DATE_FORMAT(NOW(), '%Y-%m-%dT%H:%i:%s'), DATE_FORMAT(NOW(), '%Y-%m-%dT%H:%i:%s') FROM VW_LOTE_VIDEOS WHERE CHAVE = '{{chave}}'